BEGIN;UPDATE public.engine_tournament_leases SET heartbeat_at=clock_timestamp() WHERE tournament_id='88fd351e-52e4-5765-a39b-3eef190fb755';DO $proof$ DECLARE before_image jsonb;after_image jsonb;chairs jsonb;replayed jsonb;r jsonb;BEGIN SELECT jsonb_build_object('ledger',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.chip_ledger x),'wallets',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.wallet_transactions x),'funding',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.tournament_participant_funding_receipts x),'entitlements',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.tournament_refund_entitlements x),'pool',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.spin_bonus_pools x),'reserve',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.spin_reserve_ledger x),'draw',(SELECT jsonb_agg(to_jsonb(x) ORDER BY launch_id) FROM public.spin_draw_receipts x),'profiles',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.profiles x)) INTO before_image;r:=smarter_private.continue_retired_undealt_paid_entry('88fd351e-52e4-5765-a39b-3eef190fb755');SET CONSTRAINTS ALL IMMEDIATE;SELECT jsonb_build_object('ledger',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.chip_ledger x),'wallets',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.wallet_transactions x),'funding',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.tournament_participant_funding_receipts x),'entitlements',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.tournament_refund_entitlements x),'pool',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.spin_bonus_pools x),'reserve',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.spin_reserve_ledger x),'draw',(SELECT jsonb_agg(to_jsonb(x) ORDER BY launch_id) FROM public.spin_draw_receipts x),'profiles',(SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM public.profiles x)) INTO after_image;IF before_image IS DISTINCT FROM after_image OR r->>'restored'<>'2' OR (SELECT count(*) FROM public.table_seats WHERE table_id='5df641f6-51a4-5ab7-87cc-8ef63d4e859b' AND left_at IS NULL AND stack=1000 AND NOT is_sitting_out)<>3 OR (SELECT count(*) FROM public.tournament_players WHERE tournament_id='88fd351e-52e4-5765-a39b-3eef190fb755' AND status='playing' AND chips=1000)<>3 THEN RAISE EXCEPTION 'positive paid entry conservation failed';END IF;SELECT jsonb_agg(to_jsonb(s) ORDER BY id) INTO chairs FROM public.table_seats s WHERE table_id='5df641f6-51a4-5ab7-87cc-8ef63d4e859b';replayed:=smarter_private.continue_retired_undealt_paid_entry('88fd351e-52e4-5765-a39b-3eef190fb755');IF replayed->>'replayed'<>'true' OR chairs IS DISTINCT FROM (SELECT jsonb_agg(to_jsonb(s) ORDER BY id) FROM public.table_seats s WHERE table_id='5df641f6-51a4-5ab7-87cc-8ef63d4e859b') THEN RAISE EXCEPTION 'native replay changed occupancy';END IF;IF NOT EXISTS(SELECT 1 FROM public.table_seats WHERE id='76118251-d03a-5b9f-bfe1-a18b7a6dd6a9' AND joined_at<>'2026-10-06T15:33:00.047904+00:00'::timestamptz AND occupancy_id<>'45692b2f-a5f8-5ee8-abe5-2eec4911cafe'::uuid) THEN RAISE EXCEPTION 'ordinary owner did not create successor generation';END IF;IF NOT EXISTS(SELECT 1 FROM public.table_seats WHERE id='c15ba936-6db2-59ce-9111-864ee968297e' AND joined_at<>'2026-10-06T15:32:59.417643+00:00'::timestamptz AND occupancy_id<>'7eda6429-8b60-5225-b27e-58ee0e706f2a'::uuid) THEN RAISE EXCEPTION 'ordinary owner did not create successor generation';END IF;RAISE NOTICE 'FULL_NATIVE_PAID_ENTRY_CONSERVATION_REPLAY_PASS';END;$proof$;ROLLBACK;SELECT count(*) FROM smarter_private.retirement_undealt_paid_entry_restorations;